    return frozenset((r-mr,c-mc) for r,c in s)
def dihed(s):
    outs=[]
    for k in range(4):
        t=s
        for _ in range(k): t={(c,-r) for r,c in t}
        for refl in [False,True]:
            u={(r,-c) for r,c in t} if refl else t
            outs.append(norm(u))
    return outs
