def tr(s, k, refl):
    t=set(s)
    for _ in range(k): t={(c,-r) for r,c in t}
    if refl: t={(r,-c) for r,c in t}
    lo=min(r for r,c in t); lc=min(c for r,c in t)
    t={(r-lo,c-lc) for r,c in t}
    h=max(r for r,c in t)+1; w=max(c for r,c in t)+1
    return [''.join('#' if (r,c) in t else '.' for c in range(w)) for r in range(h)]
