source='''from collections import deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            q = deque([(r, c)])
            while q:
                y, x = q.popleft()
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        cells.add((ny, nx))
                        q.append((ny, nx))
            yield color, cells


def _shape(cells):
    top = min(r for r, c in cells)
    left = min(c for r, c in cells)
    return frozenset((r-top, c-left) for r, c in cells)


def transform(grid):
    out = [row[:] for row in grid]
    components = list(_components(grid))
    templates = {}
    for color, cells in components:
        if color != 1:
            templates.setdefault(_shape(cells), color)
    for color, cells in components:
        if color == 1:
            replacement = templates.get(_shape(cells))
            if replacement is not None:
                for r, c in cells:
                    out[r][c] = replacement
    return out
